create table if not exists schedule_compute_workers(id uuid primary key default gen_random_uuid(),worker_key text not null unique,display_name text not null,worker_type text not null check(worker_type in('DB','CPU','GPU')),capabilities jsonb not null default '{}',max_parallel smallint not null default 1,health text not null default 'UNKNOWN' check(health in('HEALTHY','DEGRADED','OFFLINE','UNKNOWN')),current_load numeric not null default 0,avg_latency_ms integer,priority smallint not null default 100,active boolean not null default true,last_heartbeat timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into schedule_compute_workers(worker_key,display_name,worker_type,capabilities,max_parallel,health,priority,last_heartbeat) values('db-native','Yerleşik DB Çözücü','DB','{"solver":"generate_schedule_scenarios_v2","repair":"repair_schedule_scenario_v2","parallel_audit":true,"gpu":false}'::jsonb,4,'HEALTHY',10,now()) on conflict(worker_key) do update set capabilities=excluded.capabilities,health='HEALTHY',last_heartbeat=now(),updated_at=now();
create table if not exists schedule_solve_jobs(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code(),mode text not null default 'QUICK' check(mode in('QUICK','ADVANCED','REPAIR')),status text not null default 'QUEUED' check(status in('QUEUED','RUNNING','COMPLETED','PARTIAL','FAILED','CANCELLED')),candidate_count smallint not null default 4 check(candidate_count between 1 and 32),compute_preference text not null default 'AUTO' check(compute_preference in('AUTO','DB','CPU','GPU','HYBRID')),quality_target smallint not null default 70 check(quality_target between 0 and 100),config jsonb not null default '{}',requested_by uuid default auth.uid(),created_at timestamptz not null default now(),started_at timestamptz,finished_at timestamptz);
create index if not exists idx_schedule_solve_jobs_tenant_status on schedule_solve_jobs(institution_code,status,created_at desc);
create table if not exists schedule_solve_attempts(id uuid primary key default gen_random_uuid(),job_id uuid not null references schedule_solve_jobs(id) on delete cascade,worker_id uuid references schedule_compute_workers(id),attempt_no smallint not null,seed integer,profile_key text,status text not null default 'PLANNED' check(status in('PLANNED','RUNNING','COMPLETED','FAILED','CANCELLED')),scenario_id uuid references schedule_scenarios(id) on delete set null,score numeric,hard_issue_count integer,unplaced_count integer,duration_ms integer,diagnostics jsonb not null default '{}',started_at timestamptz,finished_at timestamptz,unique(job_id,attempt_no));
create table if not exists schedule_repair_suggestions(id uuid primary key default gen_random_uuid(),scenario_id uuid not null references schedule_scenarios(id) on delete cascade,unplaced_item_id uuid references schedule_unplaced_items(id) on delete cascade,rank smallint not null default 1,action_code text not null,title text not null,description text not null,proposed_change jsonb not null default '{}',legal_safe boolean not null default true,hard_rule_impact boolean not null default false,requires_approval boolean not null default true,estimated_gain numeric,applied_at timestamptz,created_at timestamptz not null default now());
create index if not exists idx_schedule_repair_suggestions_scenario on schedule_repair_suggestions(scenario_id,rank);
create or replace function get_schedule_compute_capabilities_v1() returns table(worker_key text,display_name text,worker_type text,health text,max_parallel smallint,current_load numeric,avg_latency_ms integer,recommended boolean) language sql stable security definer set search_path=public as $$select w.worker_key,w.display_name,w.worker_type,w.health,w.max_parallel,w.current_load,w.avg_latency_ms,(w.active and w.health in('HEALTHY','DEGRADED') and (w.last_heartbeat is null or w.last_heartbeat>now()-interval '5 minutes')) from schedule_compute_workers w where w.active order by case w.health when 'HEALTHY' then 0 when 'DEGRADED' then 1 else 2 end,w.current_load,w.priority$$;
create or replace function plan_schedule_solve_job_v1(p_mode text default 'QUICK',p_candidate_count smallint default 4,p_compute_preference text default 'AUTO',p_quality_target smallint default 70) returns uuid language plpgsql security definer set search_path=public as $$declare j uuid;w uuid;i int;begin if p_candidate_count<1 or p_candidate_count>32 then raise exception 'candidate_count 1..32 olmalıdır';end if;insert into schedule_solve_jobs(mode,candidate_count,compute_preference,quality_target,status) values(p_mode,p_candidate_count,p_compute_preference,p_quality_target,'QUEUED') returning id into j;select id into w from schedule_compute_workers where active and health in('HEALTHY','DEGRADED') and (p_compute_preference in('AUTO','HYBRID') or worker_type=p_compute_preference) order by case worker_type when 'GPU' then case when p_compute_preference in('GPU','HYBRID') then 0 else 2 end when 'CPU' then 1 else 2 end,current_load,priority limit 1;if w is null then select id into w from schedule_compute_workers where worker_key='db-native';end if;for i in 1..p_candidate_count loop insert into schedule_solve_attempts(job_id,worker_id,attempt_no,seed,status) values(j,w,i,(extract(epoch from clock_timestamp())::bigint%2147483647+i*7919)::int,'PLANNED');end loop;return j;end$$;
create or replace function refresh_schedule_repair_suggestions_v1(p_scenario_id uuid) returns integer language plpgsql security definer set search_path=public as $$declare u record;n int:=0;begin delete from schedule_repair_suggestions where scenario_id=p_scenario_id and applied_at is null;for u in select * from schedule_unplaced_items where scenario_id=p_scenario_id loop if coalesce((u.diagnostic->>'teacher_unavailable')::int,0)>0 then insert into schedule_repair_suggestions(scenario_id,unplaced_item_id,rank,action_code,title,description,proposed_change,estimated_gain) values(p_scenario_id,u.id,1,'EXPAND_TEACHER_WINDOW','Öğretmen uygunluk penceresini gözden geçir',coalesce(u.subject,'Ders')||' için yalnız soft uygunluk/tercih pencerelerini genişletmek yeni aday saat oluşturabilir.',jsonb_build_object('target','teacher_constraint','operation','relax_soft_only'),3);n:=n+1;end if;if coalesce((u.diagnostic->>'daily_limit')::int,0)>0 then insert into schedule_repair_suggestions(scenario_id,unplaced_item_id,rank,action_code,title,description,proposed_change,estimated_gain) values(p_scenario_id,u.id,2,'REBALANCE_DAILY_LOAD','Günlük yükü başka güne kaydır',coalesce(u.subject,'Ders')||' için günlük soft limit dolu. Aynı öğretmen/sınıfın daha boş günlerine yeniden dağıtım önerilir.',jsonb_build_object('target','daily_load','operation','rebalance'),2);n:=n+1;end if;if coalesce((u.diagnostic->>'consecutive_limit')::int,0)>0 then insert into schedule_repair_suggestions(scenario_id,unplaced_item_id,rank,action_code,title,description,proposed_change,estimated_gain) values(p_scenario_id,u.id,3,'RELAX_SOFT_CONSECUTIVE','Ardışık ders tercihini esnet',coalesce(u.subject,'Ders')||' için yalnız SOFT ardışıklık kuralını bir kademe esneterek tekrar dene.',jsonb_build_object('target','consecutive_soft_rule','operation','relax_one_level'),2);n:=n+1;end if;if coalesce((u.diagnostic->>'course_time_rule')::int,0)>0 then insert into schedule_repair_suggestions(scenario_id,unplaced_item_id,rank,action_code,title,description,proposed_change,estimated_gain) values(p_scenario_id,u.id,4,'REVIEW_COURSE_TIME_SOFT','Ders zaman tercihini gözden geçir',coalesce(u.subject,'Ders')||' için zaman kuralı adayları daraltıyor. HARD olmayan zaman tercihlerini gevşet.',jsonb_build_object('target','course_time_rule','operation','relax_soft_only'),2);n:=n+1;end if;if not exists(select 1 from schedule_repair_suggestions s where s.unplaced_item_id=u.id) then insert into schedule_repair_suggestions(scenario_id,unplaced_item_id,rank,action_code,title,description,proposed_change,estimated_gain) values(p_scenario_id,u.id,9,'MANUAL_REVIEW','Güvenli elle yerleştirme seçeneklerini göster',coalesce(u.subject,'Ders')||' için hard kuralları bozmadan otomatik çözüm bulunamadı. Uygun boş hücreleri ve takas seçeneklerini göster.',jsonb_build_object('target','manual_assist','operation','show_safe_slots'),1);n:=n+1;end if;end loop;return n;end$$;